svg.html:script:
const host = document.querySelector("div");
// shadow root allows for focused element while design mode is enabled.
const shadow = host.attachShadow({mode: "open"});
const focusable = document.createElementNS("http://www.w3.org/1999/xhtml", "p");
focusable.tabIndex = 0;
shadow.append(focusable);
focusable.focus();
let blurred = false;
let isAppending = false;
focusable.onblur = () => {
  blurred = isAppending ? 'duringAppend' : 'notDuringAppend';
};
document.designMode = "on";
// make focused element no longer focusable due to style
focusable.setAttribute("style","visibility:hidden");
focusable.getBoundingClientRect(); // force reflow
// blur should not happen here
isAppending = true;
shadow.append("hello");
isAppending = false;
requestAnimationFrame(() => requestAnimationFrame(() => {
  parent.postMessage(blurred);
}));
